def transform(grid):
    g = np.array(grid)
    H, W = g.shape
    bg = background(g)
    out = g.copy()
    shape = [(y, x) for y in range(H) for x in range(W) if g[y, x] == 7]
    shp = set(shape)
    markers = [(y, x) for y in range(H) for x in range(W) if g[y, x] == 2]
    vline = None; hline = None
    vedge = None; hedge = None   # which edge the marker is on
    for (y, x) in markers:
        if y == 0 or y == H - 1:
            vline = x; vedge = 'top' if y == 0 else 'bottom'
        else:
            hline = y; hedge = 'left' if x == 0 else 'right'
    # clear shape
    for (y, x) in shape:
        out[y, x] = bg
    emit(out.copy(), "Lift the 7 shape off the canvas; markers stay.")
    # draw lines
    if vline is not None:
        ys = [y for (y, x) in shape if x == vline]
        if vedge == 'top':
            rng = range(0, max(ys) + 1) if ys else range(H)
        else:
            rng = range(min(ys) if ys else 0, H)
        for y in rng:
            out[y, vline] = 7 if (y, vline) in shp else 2
    if hline is not None:
        xs = [x for (y, x) in shape if y == hline]
        if hedge == 'left':
            rng = range(0, max(xs) + 1) if xs else range(W)
        else:
            rng = range(min(xs) if xs else 0, W)
        for x in rng:
            out[hline, x] = 7 if (hline, x) in shp else 2
    if vline is not None and hline is not None:
        out[hline, vline] = 2
    emit(out.copy(), "Draw the 2 line(s) from each marker through the shape, keeping shape cells on the line as 7.")
    # group remaining cells
    groups = {}
    for (y, x) in shape:
        if x == vline or y == hline:
            continue
        if vline is not None:
            hs = 'left' if x < vline else 'right'
        else:
            hs = hedge
        if hline is not None:
            vs = 'top' if y < hline else 'bottom'
        else:
            vs = vedge
        groups.setdefault((vs, hs), []).append((y, x))
    for (vs, hs), cells in groups.items():
        if vline is not None and hline is not None:
            if vs != vedge and hs != hedge:
                continue  # quadrant touching no marker edge vanishes
        y0, x0, y1, x1 = bbox(cells)
        dy = -y0 if vs == 'top' else (H - 1 - y1)
        dx = -x0 if hs == 'left' else (W - 1 - x1)
        for (y, x) in cells:
            out[y + dy, x + dx] = 7
        emit(out.copy(), f"Move the {vs}-{hs} piece into the {vs}-{hs} corner.")
    emit(out.copy(), "Final grid.")
    return out
